export const dictionaries=Object.fromEntries(Object.entries(rows).map(([lang,row])=>{const values=row.split('|');if(values.length!==keys.length)throw new Error(`Invalid ${lang} dictionary: ${values.length}/${keys.length}`);return [lang,Object.fromEntries(keys.map((key,i)=>[key,values[i]]))];}));
export function detectLocale(languages){for(const candidate of languages){const lang=String(candidate).toLowerCase().split(/[-_]/)[0];if(names[lang])return lang;}return 'en';}
let preference='auto';try{const stored=localStorage.getItem('whisper-language');if(stored==='auto'||names[stored])preference=stored;}catch{}
export let locale=preference==='auto'?detectLocale(navigator.languages||[navigator.language]):preference;
export function t(key,vars={}){return (dictionaries[locale]?.[key]||dictionaries.en[key]||key).replace(/\{(\w+)\}/g,(_,k)=>String(vars[k]??''));}
export function duration(seconds){const minutes=Math.max(1,Math.ceil(seconds/60));return new Intl.NumberFormat(locale,{style:'unit',unit:minutes>=60?'hour':'minute',unitDisplay:'long',maximumFractionDigits:0}).format(minutes>=60?Math.ceil(minutes/60):minutes);}
export function applyLanguage(){document.documentElement.lang=locale;document.documentElement.dir=locale==='ar'?'rtl':'ltr';document.title=`Whisper. — ${t('message')}`;for(const el of document.querySelectorAll('[data-i18n]'))el.textContent=t(el.dataset.i18n);for(const attr of ['aria-label','placeholder','title'])for(const el of document.querySelectorAll(`[data-i18n-${attr}]`))el.setAttribute(attr,t(el.getAttribute(`data-i18n-${attr}`)));document.documentElement.style.setProperty('--write-placeholder',JSON.stringify(t('write')));for(const [name,key] of Object.entries({paragraph:'phParagraph',h1:'blockH1',h2:'blockH2',h3:'blockH3',list:'phList',task:'blockTask',toggle:'blockToggle',quote:'blockQuote',code:'blockCode',callout:'blockCallout',cell:'text'}))document.documentElement.style.setProperty('--ph-'+name,JSON.stringify(t(key)));updateThemeLabel();}
function updateThemeLabel(){const b=document.getElementById('theme-toggle');if(b){b.title=t(document.documentElement.dataset.theme==='dark'?'themeLight':'themeDark');b.setAttribute('aria-label',b.title);}}
export function setLanguage(value){preference=names[value]?value:'auto';locale=preference==='auto'?detectLocale(navigator.languages||[navigator.language]):preference;try{localStorage.setItem('whisper-language',preference);}catch{}applyLanguage();window.dispatchEvent(new Event('whisper-languagechange'));}
export function initLanguage(){const select=document.getElementById('language');for(const [value,name] of Object.entries(names)){const option=new Option(name,value);option.lang=value;select.add(option);}select.value=preference;select.addEventListener('change',()=>setLanguage(select.value));applyLanguage();new MutationObserver(updateThemeLabel).observe(document.documentElement,{attributes:true,attributeFilter:['data-theme']});}
